"use strict";
/* =====================================================================
   ОЛИМПИАДНЫЕ КОНТЕКСТНЫЕ ЗАДАЧИ («Бастау», «Алтын сақа», «Ақбота»…)
   Задача решается по порядку, как учат на олимпиаде:
     1 Читаю — отметить в тексте все данные (и зачеркнуть лишнее)
     2 Что найти — выбрать вопрос задачи
     3 План — расставить действия по порядку  /  Правило — найти закономерность
     4 Решаю — посчитать каждое действие (или заполнить таблицу) и записать ответ
   В тексте условия данные помечены так: ⟦7⟧ — нужное данное, ⟦!7⟧ — лишнее.
   ===================================================================== */

const D = x => `⟦${x}⟧`, X = x => `⟦!${x}⟧`;
const plainTxt = s => s.replace(/⟦!?([^⟧]*)⟧/g, "$1");
const dataOf = s => [...s.matchAll(/⟦(!?)([^⟧]*)⟧/g)].map(m => ({ x: m[1] === "!", v: m[2] }));
const pad2 = n => String(n).padStart(2, "0");
const pl = (n, a, b, c) => plural(n, a, b, c);
const pickName = (R, g) => R.pick(g ? NAMES.filter(n => n.g === g) : NAMES);
const S = (...p) => ({ ru: p.map(x => x.ru).join(" "), kz: p.map(x => x.kz).join(" ") });

