      plan: [{ t: tx("Сколько яблок стало, когда мама добавила?", "Анасы салғанда неше алма болды?"), e: `${a} + ${b}`, v: a + b }, { t: tx("Сколько осталось, когда дети съели?", "Балалар жегенде неше алма қалды?"), e: `${a + b} − ${c}`, v, need: [0] }],
      bad: tx("Сложить детей и яблоки", "Балалар мен алманы қосу"),
      unit: tx(pl(v, "яблоко", "яблока", "яблок"), "алма"),
      trap: { v: a + b, m: tx("Это сколько яблок СТАЛО. Но дети ещё съели — сделай второе действие!", "Бұл — алма саны ҚАНША БОЛҒАНЫ. Балалар әлі жеді — екінші әрекетті орында!") },
